template <class Call>
bool Run(const core::QueryArguments &a, std::vector<core::AuxRow> &out, Call call) {
  int64_t p1 = 0;
  if (!kit::ArgI64(a, 0, 0, p1))
    return false;
  std::string p2;
  if (!kit::ArgText(a, 1, p2))
    return false;
  secq3vgen_result *r = call(p1, reinterpret_cast<const uint8_t *>(p2.data()), p2.size());
  if (!r)
    return false;
  const size_t n = secq3vgen_result_len(r);
  out.reserve(out.size() + n);
  for (size_t i = 0; i < n; ++i) {
    core::AuxRow row;
    {
      const uint8_t *b0 = nullptr;
      size_t l0 = 0;
      row.values.push_back(secq3vgen_result_c0(r, i, &b0, &l0) ? kit::OutText(b0, l0) : kit::OutNull(core::AuxType::String));
    }
    {
      int64_t v1 = 0;
      row.values.push_back(secq3vgen_result_c1(r, i, &v1) ? kit::OutI64(v1) : kit::OutNull(core::AuxType::Int64));
    }
    {
      uint64_t v2 = 0;
      row.values.push_back(secq3vgen_result_c2(r, i, &v2) ? kit::OutF64(v2) : kit::OutNull(core::AuxType::Double));
    }
    out.push_back(std::move(row));
  }
  secq3vgen_result_free(r);
  return true;
}

